function SocialIcon({platform}:{platform:SocialPlatform}){const paths:Record<SocialPlatform,string>={instagram:'M7 2.8h10A4.2 4.2 0 0 1 21.2 7v10a4.2 4.2 0 0 1-4.2 4.2H7A4.2 4.2 0 0 1 2.8 17V7A4.2 4.2 0 0 1 7 2.8Zm5 4.1a5.1 5.1 0 1 0 0 10.2 5.1 5.1 0 0 0 0-10.2Zm6-1.2h.01',facebook:'M13.6 21v-8h2.7l.4-3.1h-3.1V7.9c0-.9.3-1.6 1.7-1.6h1.8V3.5c-.3 0-1.3-.1-2.4-.1-2.4 0-4 1.5-4 4.1v2.3H8v3.1h2.7v8',whatsapp:'M20.2 11.8a8.2 8.2 0 0 1-12.1 7.1L3.8 20l1.2-4.1a8.2 8.2 0 1 1 15.2-4.1Zm-5.1 3.5c.3-.2.8-.9.9-1.1.1-.2.1-.4 0-.5l-.7-.3c-.2-.1-.4-.1-.6.2l-.5.7c-.2.2-.4.2-.7.1-1.2-.6-2.1-1.5-2.7-2.7-.1-.3 0-.5.1-.7l.5-.5c.1-.2.1-.4 0-.6l-.3-.7c-.1-.2-.3-.2-.5-.2h-.4c-.2 0-.5.1-.7.3-.2.3-.8.8-.8 1.9s.8 2.2.9 2.3c.1.2 1.6 2.5 3.9 3.4 1.5.6 1.5.4 1.9.4',tiktok:'M14.2 3v11.1a3.9 3.9 0 1 1-3.2-3.8V7.2a7 7 0 1 0 6.4 6.9V8.8c1.3.9 2.8 1.4 4.3 1.4V7a6.6 6.6 0 0 1-3.1-.8A6.2 6.2 0 0 1 16.4 3Z'}; return <svg className="social-icon" width="18" height="18" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d={paths[platform]}/></svg>}
function Contact(){const [sent,setSent]=useState(false);const [message,setMessage]=useState('');const contactRows=[['gift','Email Us','hello@antzsofthaven.com','mailto:hello@antzsofthaven.com'],['user','Call Us','+94 77 123 4567','tel:+94771234567'],['heart','WhatsApp','+94 77 123 4567','https://wa.me/94771234567'],['pin','Our Location','Colombo, Sri Lanka',''] ] as const;return <><main className="contact-page"><div className="contact-breadcrumb"><a href="/" onClick={e=>{e.preventDefault();navigate('/')}}>Home</a><span>›</span><b>Contact</b></div><section className="contact-main"><div className="contact-intro"><span className="eyebrow">♥ GET IN TOUCH</span><h1>We’d love to<br/><em>hear</em> from <em>you!</em></h1><p>Whether you have a question, need help with an order, or just want to say hello—<br className="desktop-only"/> we’re here for you.</p><div className="contact-details glass-panel"><span className="contact-section-label">Socials</span>{(Object.keys(contactSocials) as SocialPlatform[]).map(platform=>{const item=contactSocials[platform];const available=Boolean(item.url);return <a className={`social-row ${platform}${available?'':' is-missing'}`} href={available?item.url:'#'} target={available?'_blank':undefined} rel={available?'noopener noreferrer':undefined} key={platform} onClick={e=>{if(!available)e.preventDefault()}}><span><SocialIcon platform={platform}/></span><div><b>{item.label}</b><small>{item.username}</small></div><i aria-hidden="true">→</i></a>})}<span className="contact-section-label contact-label">Contact</span>{contactRows.map(([icon,title,copy,url])=><a className="contact-row" href={url||'#'} key={title} onClick={e=>{if(!url)e.preventDefault()}}><span><Icon name={icon as IconName}/></span><div><b>{title}</b><small>{copy}</small></div><i aria-hidden="true">→</i></a>)}</div></div><form className="contact-form glass-panel" onSubmit={e=>{e.preventDefault();if(!message.trim())return;setSent(true);notify('Your message has been received. We’ll be in touch soon.')}}><h2>Send us a message <i>✦</i></h2><div className="contact-form-row"><label><span className="sr-only">Your Name</span><Icon name="user" size={16}/><input name="name" placeholder="Your Name" required/></label><label><span className="sr-only">Your Email</span><Icon name="gift" size={16}/><input name="email" type="email" placeholder="Your Email" required/></label></div><label className="contact-select"><span className="sr-only">How can we help you?</span><select defaultValue=""><option value="" disabled>How can we help you?</option><option>Order support</option><option>Gift recommendations</option><option>Wholesale enquiry</option></select><Icon name="chevron" size={15}/></label><label className="contact-message"><span className="sr-only">Your Message</span><Icon name="edit" size={16}/><textarea name="message" maxLength={500} value={message} onChange={e=>setMessage(e.target.value)} placeholder="Your Message" required></textarea><small>{message.length}/500</small></label><Button type="submit">{sent?'Message Sent':'Send Message'} <span>⌁</span></Button><p className="contact-response"><Icon name="lock" size={13}/> We typically reply within 24 hours</p></form><div className="contact-visual"><img src={img.contactHero} alt="Teddy bear waving from inside a glass heart"/><p><b>“</b>Every message means a lot to us.<br/>Thank you for being part of the<br/>SoftHaven family! <i>♥</i></p></div></section><section className="contact-support glass-panel">{[['heart','Fast Support','We’re here to help you quickly and kindly.'],['lock','Safe & Secure','Your privacy and information are always protected.'],['gift','Happiness Guaranteed','We’ll make sure you have the best experience.'],['truck','Islandwide Delivery','We deliver smiles across Sri Lanka.']].map(([icon,title,copy])=><div key={title}><span><Icon name={icon as IconName}/></span><div><b>{title}</b><small>{copy}</small></div></div>)}</section></main><Footer/></>}
function NotFound(){return <><main className="page simple"><span className="eyebrow">404 · Soft landing</span><h1>That page wandered off.</h1><p>We couldn’t find the page you requested. Let’s take you back to something softer.</p><Button onClick={()=>navigate('/')}>Return home</Button></main><Footer/></>}
function App(){const [path,setPath]=useState(window.location.pathname);const [cart,setCart]=useState<CartLine[]>(readCart);const [drawer,setDrawer]=useState(false);const [search,setSearch]=useState(false);useEffect(()=>{const fn=()=>setPath(window.location.pathname);window.addEventListener('popstate',fn);return()=>window.removeEventListener('popstate',fn)},[]);useEffect(()=>{localStorage.setItem('antz-soft-haven-cart',JSON.stringify(cart))},[cart]);useEffect(()=>{const metadata:Record<string,[string,string]>={'/':['ANTZ SoftHaven | Premium Plush Toys & Meaningful Gifts','Discover premium plush companions, thoughtful gifts and cuddle-worthy collections from ANTZ SoftHaven, crafted to bring comfort, joy and lasting smiles.'],'/shop':['Shop | ANTZ SoftHaven','Explore plush companions, heirloom textures, and thoughtful gifts crafted for comfort.'],'/collections':['Collections | ANTZ SoftHaven','Discover teddy bears, plush toys, gift sets and cuddly collections from ANTZ SoftHaven.'],'/checkout':['Checkout | ANTZ SoftHaven','Review your SoftHaven checkout preview. No payment is processed in this local build.'],'/account':['Account | ANTZ SoftHaven','Manage your SoftHaven account and saved preferences.'],'/wishlist':['Wishlist | ANTZ SoftHaven','Your curated gallery of SoftHaven companions.']};const slug=path.split('/').filter(Boolean).pop();const [title,description]=metadata[path]||[`${slug?slug.split('-').join(' '):'SoftHaven'} | ANTZ SoftHaven`,'Discover ANTZ SoftHaven tactile luxury plush companions and meaningful gifts.'];document.title=title;document.querySelector('meta[name="description"]')?.setAttribute('content',description);let canonical=document.querySelector('link[rel="canonical"]') as HTMLLinkElement|null;if(canonical)canonical.href=`http://localhost:5173${path}`},[path]);useEffect(()=>{const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape'){setDrawer(false);setSearch(false)}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[]);const add=(id:string)=>{setCart(c=>c.some(l=>l.productId===id)?c.map(l=>l.productId===id?{...l,quantity:l.quantity+1}:l):[...c,{productId:id,quantity:1,size:'Standard',color:'Classic Caramel'}]);setDrawer(true)};const productPath=path.startsWith('/product/')?path.split('/')[2]:'bear';let content:ReactNode=path==='/'?<Home onAdd={add}/>:path==='/collections'?<Collections onAdd={add}/>:path==='/new-arrivals'?<NewArrivalsRedirect/>:path==='/shop'?<Shop onAdd={add}/>:path==='/cart'?<Home onAdd={add}/>:path.startsWith('/product/')?<ProductPage productId={productPath} onAdd={add}/>:path==='/checkout'?<Checkout cart={cart}/>:path==='/order-confirmed'?<OrderComplete/>:path==='/account'?<Account/>:path==='/addresses'?<Addresses/>:path==='/orders'?<Orders/>:path==='/tracking'?<Tracking/>:path==='/wishlist'?<Wishlist onAdd={add}/>:path==='/rewards'?<Rewards/>:path==='/faq'?<Faq/>:path==='/login'?<AuthPage mode="login"/>:path==='/register'?<AuthPage mode="register"/>:path==='/forgot-password'?<AuthPage mode="forgot"/>:path==='/reset-password'?<AuthPage mode="reset"/>:path==='/gifts'?<SimplePage title="Thoughtful gifts, wrapped softly."/>:path==='/about'?<SimplePage title="The SoftHaven story."/>:path==='/contact'?<SimplePage title="We’re here to help."/>:['/privacy','/terms','/shipping','/returns','/cancellation','/cookies','/payment-policy'].includes(path)?<LegalPage title={path==='/privacy'?'Privacy policy.':path==='/terms'?'Terms and conditions.':path==='/shipping'?'Shipping and delivery.':path==='/returns'?'Returns and refunds.':path==='/cancellation'?'Cancellation policy.':'Payment and cookie policy.'}><p>This policy page is a launch-ready content shell. Final legal language, business identity, jurisdiction, data-retention terms, delivery rules, and payment-provider disclosures require owner/legal review before publishing.</p><h2>What this page covers</h2><p>We will publish clear information about customer data, order handling, delivery, refunds, cancellations, cookies, and payment processing here once the corresponding production services are connected.</p></LegalPage>:path==='/size-guide'?<LegalPage title="SoftHaven size guide."><p>Mini, Standard, Large, and Giant sizing are available on selected companions. Final measurements should be confirmed against the live product catalogue before launch.</p></LegalPage>:<NotFound/>;return <div><Header cartCount={cart.reduce((sum,l)=>sum+l.quantity,0)} onCart={()=>setDrawer(true)} onSearch={()=>setSearch(true)}/>{content}{drawer&&<CartDrawer cart={cart} setCart={setCart} onClose={()=>setDrawer(false)} onCheckout={()=>{setDrawer(false);navigate('/checkout')}}/>}{search&&<div className="search-modal" role="dialog" aria-modal="true" aria-label="Search SoftHaven" onClick={()=>setSearch(false)}><div onClick={e=>e.stopPropagation()}><button aria-label="Close search" onClick={()=>setSearch(false)}><Icon name="close"/></button><span className="eyebrow">Search SoftHaven</span><input autoFocus placeholder="What are you looking for?" onKeyDown={e=>{if(e.key==='Enter'){setSearch(false);navigate('/shop')}}}/><p>Try “bear”, “blanket”, or “gift”.</p></div></div>}<ToastHost/></div>}

createRoot(document.getElementById('root')!).render(<App/>);
const collectionDefinitions = [{label:'Teddy Bears',query:'Teddy Bears',image:img.bear,tone:'rose',copy:'Timeless friends for every kind of hug.'},{label:'Bunnies',query:'Bunnies',image:img.bearSmall,tone:'lilac',copy:'Soft ears and gentle company.'},{label:'Animals',query:'Animal',image:img.bearSmall,tone:'blue',copy:'A little wild, wonderfully cuddly.'},{label:'Dinosaurs',query:'Dinosaurs',image:img.bearSmall,tone:'mint',copy:'Tiny adventures, oversized comfort.'},{label:'Gift Sets',query:'Gift Sets',image:img.gift,tone:'peach',copy:'Ready-to-give moments of joy.'},{label:'Blankets & Comforters',query:'Blankets & Comforters',image:img.blanket,tone:'cream',copy:'Layers of softness for slow days.'}];
function Collections({onAdd}:{onAdd:(id:string)=>void}){const featured=products.slice(0,4),fresh=products.slice(4,8);return <><main className="collections-page"><div className="collections-bubbles" aria-hidden="true"><span></span><span></span><i>♡</i><b>✦</b></div><div className="breadcrumbs"><a href="/" onClick={e=>{e.preventDefault();navigate('/')}}>Home</a><span>›</span><b>Collections</b></div><section className="collections-hero"><div><span className="eyebrow">FIND YOUR FAVOURITE <i>♡</i></span><h1>Collections made<br/><em>to cuddle.</em></h1><p>Discover cuddly companions for every mood, moment and little celebration.</p><Button onClick={()=>navigate('/shop')}>Shop all plushies <span>→</span></Button></div><div className="collections-hero-art"><img src={img.heroPlush} alt="A group of pastel plush companions"/><span>soft friends<br/>for every heart</span></div></section><section className="collection-discovery"><div className="collections-heading"><span className="eyebrow">CURATED FOR YOU</span><h2>Explore our <em>collections.</em></h2><p>Find the perfect cuddle for every personality.</p></div><div className="collection-bento">{collectionDefinitions.map((item,index)=>{const count=products.filter(p=>p.category.includes(item.query)).length;return <a className={`collection-tile ${item.tone} tile-${index}`} href={`/shop?category=${encodeURIComponent(item.query)}`} key={item.label} onClick={e=>{e.preventDefault();navigate(`/shop?category=${encodeURIComponent(item.query)}`)}}><img loading={index>1?'lazy':undefined} src={item.image} alt={`${item.label} plush collection`}/><div className="collection-tile-caption"><span>{item.label}</span><small>{item.copy}</small><b>{count} {count===1?'friend':'friends'} <i>→</i></b></div></a>})}</div></section><section className="fresh-section"><div className="section-row"><div><span className="eyebrow">JUST LANDED <i>✦</i></span><h2>Freshly <em>arrived.</em></h2><p>Meet the newest cuddle companions.</p></div><a className="text-link" href="/shop?sort=new" onClick={e=>{e.preventDefault();navigate('/shop?sort=new')}}>View all <span>→</span></a></div><div className="collection-product-grid">{fresh.map((product,index)=><ShopCard key={product.id} product={product} onAdd={onAdd} badge={index===0?'New':'Fresh'}/>)}</div></section><section className="mood-section"><div className="collections-heading"><span className="eyebrow">A LITTLE GUIDANCE</span><h2>Find the perfect <em>cuddle.</em></h2></div><div className="mood-grid"><a href="/shop?category=Gift%20Sets" onClick={e=>{e.preventDefault();navigate('/shop?category=Gift%20Sets')}}><span><Icon name="gift"/></span><b>Gift favourites</b><small>Ready for a memorable moment.</small><i>→</i></a><a href="/shop?category=Bunnies" onClick={e=>{e.preventDefault();navigate('/shop?category=Bunnies')}}><span><Icon name="heart"/></span><b>Someone special</b><small>Soft little ways to say I care.</small><i>→</i></a><a href="/shop?category=Blankets%20%26%20Comforters" onClick={e=>{e.preventDefault();navigate('/shop?category=Blankets%20%26%20Comforters')}}><span><Icon name="star"/></span><b>Cozy days</b><small>Comfort for slow mornings.</small><i>→</i></a><a href="/shop?sort=new" onClick={e=>{e.preventDefault();navigate('/shop?sort=new')}}><span><Icon name="bag"/></span><b>New in</b><small>Meet the latest soft arrivals.</small><i>→</i></a></div></section><section className="loved-section"><div className="section-row"><div><span className="eyebrow">CURATED HAPPINESS <i>♡</i></span><h2>Most-loved <em>friends.</em></h2><p>A few especially lovely places to start.</p></div><a className="text-link" href="/shop" onClick={e=>{e.preventDefault();navigate('/shop')}}>Shop all <span>→</span></a></div><div className="collection-product-grid">{featured.map((product,index)=><ShopCard key={product.id} product={product} onAdd={onAdd} badge={index===0?'Featured':'Soft pick'}/>)}</div></section><section className="collection-feature"><div className="collection-feature-image"><img src={img.giftLifestyle} alt="A person hugging a large teddy bear"/></div><div className="collection-feature-copy"><span className="eyebrow">MADE FOR EVERY KIND OF CUDDLE</span><h2>There is a soft friend<br/><em>waiting for you.</em></h2><p>Take your time, follow your heart, and find the one that feels just right.</p><Button onClick={()=>navigate('/shop')}>Explore all plushies <span>→</span></Button></div></section><section className="all-collections"><div className="collections-heading"><span className="eyebrow">THE DIRECTORY</span><h2>All <em>collections.</em></h2></div><div className="collection-directory"><a href="/shop" onClick={e=>{e.preventDefault();navigate('/shop')}}>All plushies <span>→</span></a>{collectionDefinitions.map(item=><a key={item.label} href={`/shop?category=${encodeURIComponent(item.query)}`} onClick={e=>{e.preventDefault();navigate(`/shop?category=${encodeURIComponent(item.query)}`)}}>{item.label}<span>→</span></a>)}<a href="/shop?sort=new" onClick={e=>{e.preventDefault();navigate('/shop?sort=new')}}>New arrivals <span>→</span></a></div></section><section className="collections-cta glass-panel"><span className="eyebrow">A SOFTER START</span><h2>Still looking for <em>the one?</em></h2><p>Every cuddle begins with a little hello.</p><div><Button onClick={()=>navigate('/shop')}>Shop all plushies <span>→</span></Button><Button outline onClick={()=>navigate('/contact')}>Need help choosing?</Button></div></section></main><Footer/></>}
function NewArrivalsRedirect(){useEffect(()=>{navigate('/shop?sort=new')},[]);return null}
